class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for j in range(1, n - 1):
            for i in range(j):
                if nums[i] >= nums[j]:
                    continue
                for k in range(j + 1, n):
                    if nums[k] > nums[j]:
                        ans = max(ans, nums[i] - nums[j] + nums[k])
        return ans

