        vector<int> suf(n);
        suf[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) suf[i] = max(suf[i + 1], nums[i]);
        int pre = nums[0];
        long long ans = 0;
        for (int j = 1; j + 1 < n; j++) {
            if (pre < nums[j] && nums[j] < suf[j + 1])
                ans = max(ans, (long long)pre - nums[j] + suf[j + 1]);
            pre = min(pre, nums[j]);
        }
        return (int)ans;
    }
};

